setup_yaml:
# Job setup for examples/demo_5axis.nc
units: mm

# Tool table. length = gauge line to tip (what the H offset holds).
# type: flat | ball | bull | drill | spot | chamfer. Holder: [height, lower dia, upper dia] segments
# from the tool end up to the gauge line (or holder_diameter + holder_length for a plain cylinder).
# A Fusion 360 / CSV library can be pulled in with `tool_library: file` (see umc_twin/toollib.py).
tools:
  1: {name: "50 mm face mill", type: flat, length: 110.0, diameter: 50.0, flute_length: 8.0,
      holder: [[25, 40, 40], [30, 63, 63]]}
  2: {name: "10 mm endmill", type: flat, length: 90.0, diameter: 10.0, flute_length: 25.0,
      holder: [[35, 20, 32], [15, 50, 50]]}
  3: {name: "6.8 mm drill", type: drill, length: 120.0, diameter: 6.8, flute_length: 40.0,
      holder_diameter: 25.0, holder_length: 55.0}
  4: {name: "12 mm 90deg chamfer", type: chamfer, length: 95.0, diameter: 12.0, flute_length: 8.0,
      holder: [[35, 20, 32], [15, 50, 50]]}

# Part zero. table_point is in the table frame (origin = B/C pivot, platter top at Z -50.8).
# Stock (100 dia x 50) sits on a 60 tall riser: bottom at 9.2, top face at 59.2.
# The riser lifts the part clear of the platter for the tilted operations.
work_offsets:
  G54: {table_point: [0, 0, 59.2]}

stock: {type: cylinder, size: [100, 50], position: [0, 0, 9.2]}

# Work material for the spindle-load estimate; resolution = voxel size of the cutting sim (mm).
material: {name: aluminum_6061, resolution: 0.625}

fixtures:
  - {name: riser, type: cylinder, size: [80, 60], position: [0, 0, -50.8]}
